package com.aaliyun.leadnews.ai.service;
import com.aaliyun.leadnews.ai.config.*;import com.aaliyun.leadnews.ai.exception.AiExceptions;import org.junit.jupiter.api.Test;import java.awt.*;import java.awt.image.BufferedImage;import java.io.*;import java.time.Duration;import java.util.List;import javax.imageio.ImageIO;import static org.assertj.core.api.Assertions.*;
class TrustedMediaLoaderTest {
 private ArticleAuditProperties audit(){return new ArticleAuditProperties(5,20000,"leadnews",List.of("material/"),5242880,524288,2097152,3145728,1280,.8);}
 private AiProperties ai(){return new AiProperties("qwen3.8-max",.3,1024,Duration.ofSeconds(30),Duration.ofSeconds(60),1,Duration.ofMillis(200),4,1,5242880,List.of("localhost"));}
 @Test void resizesAndCompressesAuditCopyWithoutChangingSource()throws Exception{var source=new BufferedImage(2000,1000,BufferedImage.TYPE_INT_RGB);var g=source.createGraphics();g.setColor(Color.BLUE);g.fillRect(0,0,2000,1000);g.dispose();var raw=new ByteArrayOutputStream();ImageIO.write(source,"png",raw);byte[] original=raw.toByteArray();var audit=new ArticleAuditProperties(5,20000,"leadnews",List.of("material/"),5242880,524288,2097152,3145728,1280,.8);var ai=new AiProperties("qwen3.8-max",.3,1024,Duration.ofSeconds(30),Duration.ofSeconds(60),1,Duration.ofMillis(200),4,1,5242880,List.of("localhost"));byte[] compressed=new TrustedMediaLoader(null,audit,ai).compress(original);var decoded=ImageIO.read(new ByteArrayInputStream(compressed));assertThat(decoded.getWidth()).isEqualTo(1280);assertThat(decoded.getHeight()).isEqualTo(640);assertThat(compressed.length).isLessThanOrEqualTo(524288);assertThat(original).isEqualTo(raw.toByteArray());}
 @Test void rejectsMoreThanFiveBeforeTouchingMinio(){var loader=new TrustedMediaLoader(null,audit(),ai());assertThatThrownBy(()->loader.load(List.of("material/1","material/2","material/3","material/4","material/5","material/6"))).isInstanceOf(AiExceptions.InvalidImage.class);}
}
